    internal static Vector3[] Get(Mesh mesh, string modelPath) => Cache.GetValue(mesh, m => new Result(Read(m, modelPath))).Points;
    private static Vector3[] Read(Mesh mesh, string modelPath)
    {
        if (!mesh.Name.StartsWith("#weapon", StringComparison.OrdinalIgnoreCase) || mesh.Draw?.VertexBuffers is not { Length: > 0 } buffers || mesh.Draw.IndexBuffer == null) return [];
        try
        {
            var vb = buffers[0]; var ib = mesh.Draw.IndexBuffer;
            var position = vb.Declaration.VertexElements.FirstOrDefault(e => e.SemanticName == "POSITION");
            if (vb.Buffer == null || ib.Buffer == null) return [];
            if (position.SemanticName != "POSITION" || position.AlignedByteOffset < 0 || vb.Count <= 0 || vb.Count > 10000 || ib.Count <= 0 || ib.Count > 60000) return [];
            ReadOnlySpan<byte> vertexBytes = vb.Buffer.GetSerializationData()?.Content is { } vbData ? vbData : ModelEffectHelper.GetModelVertexBufferData(modelPath);
            ReadOnlySpan<byte> indexBytes = ib.Buffer.GetSerializationData()?.Content is { } ibData ? ibData : ModelEffectHelper.GetModelIndexBufferData(modelPath);
            using var hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
            for (var i = 0; i < vb.Count; i++) hash.AppendData(vertexBytes.Slice(vb.Offset + i * vb.Stride + position.AlignedByteOffset, 12));
            Span<byte> index = stackalloc byte[4];
            for (var i = 0; i < ib.Count; i++)
            {
                var value = ib.Is32Bit ? BitConverter.ToInt32(indexBytes.Slice(ib.Offset + i * 4, 4)) : BitConverter.ToUInt16(indexBytes.Slice(ib.Offset + i * 2, 2));
                System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(index, value); hash.AppendData(index);
            }
            return Known.TryGetValue(Convert.ToHexString(hash.GetHashAndReset()), out var points) ? points : [];
        }
        catch (Exception ex) when (ex is ArgumentException or IndexOutOfRangeException or InvalidOperationException or IOException || ex.GetType().FullName == "Stride.Core.Serialization.Contents.ContentManagerException") { return []; }
    }
